import std.collection.*
import std.reflect.*
import std.convert.*

class ArgumentParser {
    let arguments: HashMap<String, Any>
    let required: HashSet<String>
    let types: HashMap<String, TypeInfo>

    public init() {
        arguments = HashMap<String, Any>()
        required = HashSet<String>()
        types = HashMap<String, TypeInfo>()
    }

    public func parse_arguments(command_string: String): (Bool, Option<HashSet<String>>) {
        let parts = command_string.split(" ")
        let args = ArrayList<String>()
        for (i in 1..parts.size) {
            args.append(parts[i])
        }
        for (i in 0..args.size) {
            let arg = args[i]
            if (arg.startsWith("--")) {
                let keyValue = arg.substring(2).split("=")
                if (keyValue.size == 2) {
                    let key = keyValue[0]
                    let value = keyValue[1]
                    arguments[key] = convert_type(key, value)
                } else {
                    arguments[keyValue[0]] = true
                }
            } else if (arg.startsWith("-")) {
                let key = arg.substring(1)
                if (i + 1 < args.size && !args[i + 1].startsWith("-")) {
                    arguments[key] = convert_type(key, args[i + 1])
                } else {
                    arguments[key] = true
                }
            }
        }
        let missing = HashSet<String>()
        for (req in required) {
            if (!arguments.contains(req)) {
                missing.insert(req)
            }
        }
        if (missing.size > 0) {
            return (false, Some(missing))
        } else {
            return (true, None)
        }
    }

    public func get_argument(key: String): Any {
        return arguments.get(key).getOrNone()
    }

    public func add_argument(arg: String, required!: Bool = false, arg_type!: TypeInfo = TypeInfo.of<String>()): Unit {
        if (required) {
            required.insert(arg)
        }
        types[arg] = arg_type
    }

    public func convert_type(arg: String, value: String): Any {
        let typeInfo = types.get(arg)
        if (typeInfo.isNone()) {
            return value
        }
        let ti = typeInfo.get()
        if (ti == TypeInfo.of<Int64>()) {
            return Int64.parse(value)
        } else if (ti == TypeInfo.of<Bool>()) {
            return value == "true"
