public class ExpressionParser {
    public static func parseNumber(): Parser < Expr > {
        return wrap(integer()).map({ n: Int64 => Expr.Number(n) })
    }
    public static func parseVariable(): Parser < Expr > {
        return wrap(identifier()).map({ id: String => Expr.Variable(id) })
    }
    public static func parseParentheses(): Parser < Expr > {
        let openParen = wrap(char(r'('))
        let closeParen = wrap(char(r')'))
        return openParen.flatMap({ _: Rune => parseExpression() }).flatMap({ expr: Expr => closeParen.map({ _: Rune => Expr.Parentheses(expr) }) })
    }
    public static func parseFactor(): Parser < Expr > {
        let numberOps = ops(parseNumber())
        let variableOps = ops(parseVariable())
        let parenOps = ops(parseParentheses())
        return numberOps | variableOps | parenOps
    }
    public static func parseTerm(): Parser < Expr > {
        return wrap(parseFactor()).flatMap({ left: Expr => parseTermTail(left) })
    }
    private static func parseTermTail(left: Expr): Parser < Expr > {
        let mulOp = wrap(spaces()).flatMap({ _: ArrayList < Rune > => wrap(char(r'*')).flatMap({ _: Rune => wrap(spaces()).map({ _: ArrayList < Rune > => "mul" }) }) })
        let divOp = wrap(spaces()).flatMap({ _: ArrayList < Rune > => wrap(char(r'/')).flatMap({ _: Rune => wrap(spaces()).map({ _: ArrayList < Rune > => "div" }) }) })
        let opParser = mulOp.or(divOp)
        return opParser.flatMap({ op: String => wrap(parseFactor()).flatMap({ right: Expr => let result = match(op) {
                    case "mul" => Expr.Multiply(left, right)
                    case "div" => Expr.Divide(left, right)
                    case _ => left
                }

                parseTermTail(result) }) }).or(success(left))
    }
    public static func parseExpression(): Parser < Expr > {
        return wrap(parseTerm()).flatMap({ left: Expr => parseExpressionTail(left) })
    }
    private static func parseExpressionTail(left: Expr): Parser < Expr > {
        let addOp = wrap(spaces()).flatMap({ _: ArrayList < Rune > => wrap(char(r'+')).flatMap({ _: Rune => wrap(spaces()).map({ _: ArrayList < Rune > => "add" }) }) })
        let subOp = wrap(spaces()).flatMap({ _: ArrayList < Rune > => wrap(char(r'-')).flatMap({ _: Rune => wrap(spaces()).map({ _: ArrayList < Rune > => "sub" }) }) })
        let opParser = addOp.or(subOp)
        return opParser.flatMap({ op: String => wrap(parseTerm()).flatMap({ right: Expr => let result = match(op) {
                    case "add" => Expr.Add(left, right)
                    case "sub" => Expr.Subtract(left, right)
                    case _ => left
                }

                parseExpressionTail(result) }) }).or(success(left))
    }
    public static func parse(input: String): ParseResult < Expr > {
        let inputStream = Input(input)
        let parser = wrap(spaces()).flatMap({ _: ArrayList < Rune > => wrap(parseExpression()).flatMap({ expr: Expr => wrap(spaces()).map({ _: ArrayList < Rune > => expr }) }) })
        return parser.parse(inputStream)
    }
}
