public class ProjectKnowledgeGraphBuilder {
    private var projectRoot: String
    private var knowledgeGraph: HashMap < String, ArrayList < String >>
    private var entityRelations: HashMap < String, HashMap < String, String >>
    public init(projectRoot: String) {
        this.projectRoot = projectRoot
        this.knowledgeGraph = HashMap < String, ArrayList < String >>()
        this.entityRelations = HashMap < String, HashMap < String, String >>()
        println("🏗️ 项目知识图谱构建器已初始化: ${projectRoot}")
    }
    public func buildKnowledgeGraph(): String {
        println("🏗️ 开始构建项目知识图谱...")
        let projectFiles = scanProjectFiles()
        println("📁 扫描到 ${projectFiles.size} 个文件")
        for(file in projectFiles) {
            extractEntitiesAndRelations(file)
        }
        buildRelationshipGraph()
        return generateKnowledgeGraphReport()
    }
    private func scanProjectFiles(): Array < String > {
        return["${projectRoot}/src/main.cj", "${projectRoot}/src/agents/agent.cj", "${projectRoot}/src/tools/tool.cj", "${projectRoot}/src/rag/retriever.cj"]
    }
    private func extractEntitiesAndRelations(filePath: String): Unit {
        let fileName = extractFileName(filePath)
        let entities = ArrayList < String >()
        if(fileName.contains("agent")) {
            entities.add("Agent")
            entities.add("AgentExecutor")
            entities.add("AgentRequest")
        }
        else if(fileName.contains("tool")) {
            entities.add("Tool")
            entities.add("ToolManager")
            entities.add("ToolResult")
        }
        else if(fileName.contains("rag")) {
            entities.add("Retriever")
            entities.add("Document")
            entities.add("Vector")
        }
        knowledgeGraph[fileName] = entities
        let relations = HashMap < String, String >()
        for(entity in entities) {
            relations[entity] = "defined_in"
        }
        entityRelations[fileName] = relations
    }
    private func buildRelationshipGraph(): Unit {
        println("🔗 构建实体关系图...")
        for((file, entities) in knowledgeGraph) {
            for(entity in entities) {
                if(entity == "Agent" && knowledgeGraph.contains("tool.cj")) {
                    addRelation(entity, "uses", "Tool")
                }
                else if(entity == "Tool" && knowledgeGraph.contains("retriever.cj")) {
                    addRelation(entity, "integrates", "Retriever")
                }
            }
        }
    }
    private func addRelation(entity1: String, relation: String, entity2: String): Unit {
        let relationKey = "${entity1}_${relation}_${entity2}"
        println("🔗 添加关系: ${relationKey}")
    }
    private func generateKnowledgeGraphReport(): String {
        var report = "🧠 **项目知识图谱报告**\n\n"
        report += "📁 项目根目录: ${projectRoot}\n"
        report += "📊 文件数量: ${knowledgeGraph.size}\n"
        var totalEntities = 0
        for((file, entities) in knowledgeGraph) {
            totalEntities += entities.size
        }
        report += "🏷️ 实体总数: ${totalEntities}\n\n"
        report += "📋 **文件实体映射**:\n"
        for((file, entities) in knowledgeGraph) {
            report += "- ${file}: ${entities.size} 个实体\n"
            for(entity in entities) {
                report += "  • ${entity}\n"
            }
        }
        return report
    }
