import std.convert.Parsable

class BigNumCalculator {

    public static func add(num1: String, num2: String): String {
        let maxLength = max(num1.size, num2.size)
        let n1 = num1.padStart(maxLength, '0')
        let n2 = num2.padStart(maxLength, '0')

        var carry = 0
        var result = ""
        for (i in maxLength - 1..-1) {
            let digitSum = Int64.parse(n1[i].toString()) + Int64.parse(n2[i].toString()) + carry
            carry = digitSum / 10
            let digit = digitSum % 10
            result = digit.toString() + result
        }
        if (carry > 0) {
            result = carry.toString() + result
        }
        return result
    }

    public static func subtract(num1: String, num2: String): String {
        var n1 = num1
        var n2 = num2
        var negative = false

        if (n1.size < n2.size) {
            swap(n1, n2)
            negative = true
        } else if (n1.size == n2.size) {
            if (n1 < n2) {
                swap(n1, n2)
                negative = true
            }
        }

        let maxLength = max(n1.size, n2.size)
        n1 = n1.padStart(maxLength, '0')
        n2 = n2.padStart(maxLength, '0')

        var borrow = 0
        var result = ""
        for (i in maxLength - 1..-1) {
            var digitDiff = Int64.parse(n1[i].toString()) - Int64.parse(n2[i].toString()) - borrow
            if (digitDiff < 0) {
                digitDiff += 10
                borrow = 1
            } else {
                borrow = 0
            }
            result = digitDiff.toString() + result
        }

        while (result.size > 1 && result[0] == '0') {
            result = result[1..]
        }

        if (negative && result != "0") {
            result = "-" + result
        }
        return result
    }

    public static func multiply(num1: String, num2: String): String {
        let len1 = num1.size
        let len2 = num2.size
        var result = Array<Int64>(len1 + len2, item: 0)

        for (i in len1 - 1..-1) {
            for (j in len2 - 1..-1) {
                let mul = Int64.parse(num1[i].toString()) * Int64.parse(num2[j].toString())
                let p1 = i + j
                let p2 = i + j + 1
                let total = mul + result[p2]
                result[p1] += total / 10
                result[p2] = total % 10
            }
        }

        var start = 0
        while (start < result.size - 1 && result[start] == 0) {
            start += 1
        }

        var output = ""
        for (k in start..result.size) {
            output += result[k].toString()
        }
        return output
    }
}

