class BinaryDataProcessor {
    var binary_string: String

    public init(binary_string: String) {
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        var cleaned = StringBuilder()
        for (c in this.binary_string) {
            if (c == '0' || c == '1') {
                cleaned.append(c)
            }
        }
        this.binary_string = cleaned.toString()
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        let zeroes = this.binary_string.count('0')
        let ones = this.binary_string.count('1')
        let total = this.binary_string.size
        let zeroPct = Float64(zeroes) / Float64(total)
        let onePct = Float64(ones) / Float64(total)
        return HashMap<String, Float64>([("Zeroes", zeroPct), ("Ones", onePct), ("Bit length", Float64(total))])
    }

    public func convert_to_ascii(): String {
        let bytes = this.toByteArray()
        return String.fromUtf8(bytes)
    }

    public func convert_to_utf8(): String {
        let bytes = this.toByteArray()
        return String.fromUtf8(bytes)
    }

    private func toByteArray(): Array<Byte> {
        let len = this.binary_string.size
        var bytes = ArrayList<Byte>()
        for (i in 0..len/8) {
            let chunk = this.binary_string[i*8..i*8+8]
            let decimal = Int64.parse(chunk, radix: 2)
            bytes.append(decimal.toByte())
        }
        return bytes
    }
}

