import std.convert.Parsable
import std.collection.Stack

class Calculator {
    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        let operandStack = Stack<Float64>()
        let operatorStack = Stack<String>()
        var numBuffer = ""

        for (c in expression) {
            let ch = c.toString()
            if (ch.matches(Regex("[0-9.]"))) {
                numBuffer += ch
            } else {
                if (!numBuffer.isEmpty()) {
                    operandStack.push(Float64.parse(numBuffer))
                    numBuffer = ""
                }

                if (operators.contains(ch) || ch == "+" || ch == "-" || ch == "*" || ch == "/" || ch == "^") {
                    while (!operatorStack.isEmpty() && operatorStack.top() != "(" && precedence(operatorStack.top()!) >= precedence(ch)) {
                        applyOperator(operandStack, operatorStack)
                    }
                    operatorStack.push(ch)
                } else if (ch == "(") {
                    operatorStack.push(ch)
                } else if (ch == ")") {
                    while (!operatorStack.isEmpty() && operatorStack.top() != "(") {
                        applyOperator(operandStack, operatorStack)
                    }
                    if (!operatorStack.isEmpty()) {
                        operatorStack.pop()
                    }
                }
            }
        }

        if (!numBuffer.isEmpty()) {
            operandStack.push(Float64.parse(numBuffer))
        }

        while (!operatorStack.isEmpty()) {
            applyOperator(operandStack, operatorStack)
        }

        if (operandStack.isEmpty()) {
            return None
        } else {
            return Some(operandStack.top()!)
        }
    }

    public func precedence(op: String): Int64 {
        match (op) {
            case "+" => 1
            case "-" => 1
            case "*" => 2
            case "/" => 2
            case "^" => 3
            case _ => 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        let op = operator_stack.removeAt(operator_stack.size() - 1)
        let b = operand_stack.removeAt(operand_stack.size() - 1)
        let a = operand_stack.removeAt(operand_stack.size() - 1)
        let result = operators[op]!!(a, b)
        operand_stack.append(result)
        (operand_stack, operator_stack)
    }

    private func applyOperator(operandStack: Stack<Float64>, operatorStack: Stack<String>): Unit {
        let op = operatorStack.pop()!
        let b = operandStack.pop()!
        let a = operandStack.pop()!
        let result = operators[op]!!(a, b)
        operandStack.push(result)
    }
