        let dayStart = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let dayEnd   = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 23, minute: 59)
        var current = dayStart
        while (current < dayEnd) {
            let slotEnd = current + Duration.minute * 60
            if (this.is_available(current, slotEnd)) {
                slots.append((current, slotEnd))
            }
            current = current + Duration.minute * 60
        }
        return slots
    }

