import std.collection.ArrayList
import std.collection.*

class ChandrasekharSieve {
    let n: Int64
    var primes: ArrayList<Int64>

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if (this.n < 2) {
            return ArrayList<Int64>()
        }
        let size = this.n + 1
        var sieve = ArrayList<Bool>(size, item: true)
        sieve[0] = false
        sieve[1] = false
        var p: Int64 = 2
        while (p * p <= this.n) {
            if (sieve[p]) {
                var i = p * p
                while (i <= this.n) {
                    sieve[i] = false
                    i += p
                }
            }
            p += 1
        }
        var primes = ArrayList<Int64>()
        for (i in 2..=this.n) {
            if (sieve[i]) {
                primes.append(i)
            }
        }
        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        return this.primes
    }
}

