public class RadixSort {
    private static let CUT_OFF: Int64 = 40
    private static let MAX_DIGITS: Int64 = 64
    private static let MAX_D: Int64 = 8
    private static let SIZE_RADIX: Int64 = 1 <<(MAX_DIGITS / MAX_D)
    private static let MASK: Int64 = SIZE_RADIX - 1
    private static func radixSort(list: ArrayList < Int64 >, n: Int64, tempArray: ArrayList < Int64 >, cnt: ArrayList < Int64 >) {
        var shift: Int64 = 0
        for(_ in 0 .. MAX_D) {
            for(i in 0 ..= SIZE_RADIX - 1) {
                cnt.append(0)
            }
            for(i in 0 ..= n - 1) {
                cnt[(list[i] >> shift) & MASK] += 1
            }
            for(i in 1 ..= SIZE_RADIX - 1) {
                cnt[i] += cnt[i - 1]
            }
            for(i in SIZE_RADIX - 1 ..= 0) {
                cnt[(list[i] >> shift) & MASK] -= 1
                tempArray[cnt[(list[i] >> shift) & MASK]] = list[i]
            }
        }
        for(i in 0 ..= n - 1) {
            list[i] = tempArray[i]
        }
    }
    public static func sort(list: ArrayList < Int64 >): Unit {
        if(list.isEmpty() || list.size == 1) {
            return
        }
        if(list.size <= CUT_OFF) {
            list.sort(stable: true)
            return
        }
        let n: Int64 = list.size
        var workArray: ArrayList < Int64 >= ArrayList < Int64 >(n, { _idx => 0 })
        for(i in 0 .. n) {
            workArray[i] = list[i]
        }
        var tempArrayForHelper: ArrayList < Int64 >= ArrayList < Int64 >(n, { _idx => 0 })
        var countForHelper: ArrayList < Int64 >= ArrayList < Int64 >(SIZE_RADIX, { _idx => 0 })
        radixSort(workArray, n, tempArrayForHelper, countForHelper)
        for(i in 0 .. n) {
            list[i] = workArray[i]
        }
    }
}
