class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        let file = File(file_name, mode=FileMode.READ)
        let reader = BufferedReader(file)
        var first = true
        while (true) {
            let line = reader.readLine()
            if (line.isNone()) {
                break
            }
            let row = line.get().split(',')
            if (first) {
                for (cell in row) {
                    title.append(cell)
                }
                first = false
            } else {
                let rowList = ArrayList<String>()
                for (cell in row) {
                    rowList.append(cell)
                }
                data.append(rowList)
            }
        }
        reader.close()
        (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        try {
            let file = File(file_name, mode=FileMode.WRITE)
            let writer = BufferedWriter(file)
            for (row in data) {
                let line = row.join(',')
                writer.write(line)
                writer.newLine()
            }
            writer.close()
            1
        } catch (_) {
            0
        }
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        let column_data = ArrayList<String>()
        for (row in data) {
            if (N < row.size()) {
                let cell = row[N].toUpperCase()
                column_data.append(cell)
            }
        }
        let new_data = ArrayList<ArrayList<String>>()
        new_data.append(title)
        new_data.append(column_data)
        let new_name = "${save_file_name.split('.')[0]}_process.csv"
        write_csv(new_data, new_name)
    }
}

