class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        let sum: Int64 = 0
        for (x in data) {
            sum += x
        }
        round(Float64(sum) / Float64(n) * 100.0) / 100.0
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let n = data.size
        if (n == 0) {
            return 0.0
        }
        let sorted = ArrayList<Int64>(data)
        sort(sorted)
        if (n % 2 == 0) {
            let mid = n / 2
            round(Float64(sorted[mid - 1] + sorted[mid]) / 2.0 * 100.0) / 100.0
        } else {
            let mid = n / 2
            round(Float64(sorted[mid]) * 100.0) / 100.0
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counter = HashMap<Int64, Int64>()
        for (x in data) {
            counter[x] = counter.getOrDefault(x, 0) + 1
        }
        var maxCount: Int64 = 0
        for (count in counter.values()) {
            if (count > maxCount) {
                maxCount = count
            }
        }
        let modes = ArrayList<Int64>()
        for ((x, count) in counter) {
            if (count == maxCount) {
                modes.append(x)
            }
        }
        sort(modes)
        modes
    }
}

