import std.convert.*

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size
        let mean1 = data1.reduce(0.0, {acc, x => acc + x}) / Float64(n)
        let mean2 = data2.reduce(0.0, {acc, x => acc + x}) / Float64(n)

        var numerator = 0.0
        for (i in 0..n) {
            numerator += (data1[i] - mean1) * (data2[i] - mean2)
        }

        var sum1 = 0.0
        var sum2 = 0.0
        for (i in 0..n) {
            sum1 += (data1[i] - mean1) * (data1[i] - mean1)
            sum2 += (data2[i] - mean2) * (data2[i] - mean2)
        }
        let denominator = sqrt(sum1) * sqrt(sum2)

        return if (denominator != 0.0) { numerator / denominator } else { 0.0 }
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.reduce(0.0, {acc, x => acc + x}) / Float64(n)
        let variance = data.reduce(0.0, {acc, x => acc + (x - mean) * (x - mean)}) / Float64(n)
        let std_deviation = sqrt(variance)

        if (std_deviation == 0.0) {
            return 0.0
        }

        var sum_cubed = 0.0
        for (x in data) {
            sum_cubed += (x - mean) * (x - mean) * (x - mean)
        }
        let skewness = sum_cubed * Float64(n) / (Float64(n - 1) * Float64(n - 2) * std_deviation * std_deviation * std_deviation)
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size
        let mean = data.reduce(0.0, {acc, x => acc + x}) / Float64(n)
        let variance = data.reduce(0.0, {acc, x => acc + (x - mean) * (x - mean)}) / Float64(n)
        let std_dev = sqrt(variance)

        if (std_dev == 0.0) {
            return Float64.nan
        }

        var fourth_moment = 0.0
        for (x in data) {
            let centered = x - mean
            fourth_moment += centered * centered * centered * centered
        }
        fourth_moment /= Float64(n)

        let kurtosis_value = (fourth_moment / (std_dev * std_dev * std_dev * std_dev)) - 3.0
        return kurtosis_value
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        var pdf_values = ArrayList<Float64>()
        for (x in data) {
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            pdf_values.append(coeff * exp(exponent))
        }
        return pdf_values
    }
}

