class DecryptionUtils {
    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        var plaintext = ""
        for (c in ciphertext) {
            if (c >= 'A' && c <= 'Z') {
                let base = 65
                let shifted = ((c.toInt64() - base - shift + 26) % 26) + base
                plaintext += Char(shifted)
            } else if (c >= 'a' && c <= 'z') {
                let base = 97
                let shifted = ((c.toInt64() - base - shift + 26) % 26) + base
                plaintext += Char(shifted)
            } else {
                plaintext += c
            }
        }
        return plaintext
    }

    public func vigenere_decipher(ciphertext: String): String {
        var decrypted = ""
        var keyIndex = 0
        for (c in ciphertext) {
            if (c >= 'A' && c <= 'Z') {
                let keyChar = key[keyIndex % key.size].toLower()
                let shift = keyChar.toInt64() - 97
                let base = 65
                let shifted = ((c.toInt64() - base - shift + 26) % 26) + base
                decrypted += Char(shifted)
                keyIndex += 1
            } else if (c >= 'a' && c <= 'z') {
                let keyChar = key[keyIndex % key.size].toLower()
                let shift = keyChar.toInt64() - 97
                let base = 97
                let shifted = ((c.toInt64() - base - shift + 26) % 26) + base
                decrypted += Char(shifted)
                keyIndex += 1
            } else {
                decrypted += c
            }
        }
        return decrypted
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let n = encrypted_text.size
        var fence = ArrayList<ArrayList<Char>>()
        for (i in 0..rails) {
            fence.append(ArrayList<Char>())
            for (j in 0..n) {
                fence[i].append('\n')
            }
        }

        var dir = -1
        var row = 0
        var col = 0
        for (i in 0..n) {
            if (row == 0 || row == rails - 1) {
                dir = -dir
            }
            fence[row][col] = '*'
            col += 1
            row += dir
        }

        var index = 0
        for (i in 0..rails) {
            for (j in 0..n) {
                if (fence[i][j] == '*') {
                    fence[i][j] = encrypted_text[index]
                    index += 1
                }
            }
        }

        var result = ""
        dir = -1
        row = 0
        col = 0
        for (i in 0..n) {
            if (row == 0 || row == rails - 1) {
                dir = -dir
            }
            result += fence[row][col]
            col += 1
            row += dir
        }
        return result
    }
}

