import std.collection.*

public class EightPuzzle {
    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([
            ArrayList<Int64>([1, 2, 3]),
            ArrayList<Int64>([4, 5, 6]),
            ArrayList<Int64>([7, 8, 0])
        ])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (0, 0)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let (i, j) = find_blank(state)
        let new_state = ArrayList<ArrayList<Int64>>()
        for (row in state) {
            new_state.append(ArrayList<Int64>(row))
        }

        if (direction == "up" && i > 0) {
            new_state[i][j] = new_state[i-1][j]
            new_state[i-1][j] = 0
        } else if (direction == "down" && i < 2) {
            new_state[i][j] = new_state[i+1][j]
            new_state[i+1][j] = 0
        } else if (direction == "left" && j > 0) {
            new_state[i][j] = new_state[i][j-1]
            new_state[i][j-1] = 0
        } else if (direction == "right" && j < 2) {
            new_state[i][j] = new_state[i][j+1]
            new_state[i][j+1] = 0
        }
        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state)
        if (i > 0) { moves.append("up") }
        if (i < 2) { moves.append("down") }
        if (j > 0) { moves.append("left") }
        if (j < 2) { moves.append("right") }
        return moves
    }

    public func solve(): ?ArrayList<String> {
        let open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        let closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()
        open_list.append((initial_state, ArrayList<String>()))

        while (open_list.size > 0) {
            let (current_state, path) = open_list.remove(0)
            if (is_goal(current_state)) {
                return path
            }
            closed_list.append(current_state)
            for (move_dir in get_possible_moves(current_state)) {
                let new_state = move(current_state, move_dir)
                if (!contains(closed_list, new_state)) {
                    open_list.append((new_state, ArrayList<String>(path).append(move_dir)))
                }
            }
        }
        return None
    }

    private func is_goal(state: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] != goal_state[i][j]) {
                    return false
                }
            }
        }
        return true
    }

    private func contains(list: ArrayList<ArrayList<ArrayList<Int64>>>, state: ArrayList<ArrayList<Int64>>): Bool {
        for (s in list) {
            if (equals(s, state)) { return true }
        }
        return false
    }

    private func equals(a: ArrayList<ArrayList<Int64>>, b: ArrayList<ArrayList<Int64>>): Bool {
        for (i in 0..3) {
            for (j in 0..3) {
                if (a[i][j] != b[i][j]) { return false }
            }
        }
        return true
    }
}

