import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        var ciphertext = ""
        for (char in plaintext) {
            if (char >= 'A' && char <= 'Z') {
                let offset = ((char.toInt64() - 65 + shift) % 26 + 26) % 26
                ciphertext += Char.fromInt64(offset + 65)
            } else if (char >= 'a' && char <= 'z') {
                let offset = ((char.toInt64() - 97 + shift) % 26 + 26) % 26
                ciphertext += Char.fromInt64(offset + 97)
            } else {
                ciphertext += char
            }
        }
        return ciphertext
    }

    public func vigenere_cipher(plain_text: String): String {
        var encrypted_text = ""
        var key_index = 0
        for (char in plain_text) {
            if (char >= 'A' && char <= 'Z') {
                let shift = (this.key[key_index % this.key.size].toInt64() - 97)
                let encrypted_char = Char.fromInt64(((char.toInt64() - 65 + shift) % 26) + 65)
                encrypted_text += encrypted_char
                key_index += 1
            } else if (char >= 'a' && char <= 'z') {
                let shift = (this.key[key_index % this.key.size].toInt64() - 97)
                let encrypted_char = Char.fromInt64(((char.toInt64() - 97 + shift) % 26) + 97)
                encrypted_text += encrypted_char
                key_index += 1
            } else {
                encrypted_text += char
            }
        }
        return encrypted_text
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        var fence = ArrayList<ArrayList<Char>>()
        for (i in 0..rails) {
            fence.append(ArrayList<Char>())
            for (j in 0..plain_text.size) {
                fence[i].append('\n')
            }
        }
        var direction: Int64 = -1
        var row = 0
        var col = 0
        for (char in plain_text) {
            if (row == 0 || row == rails - 1) {
                direction = -direction
            }
            fence[row][col] = char
            col += 1
            row += direction
        }
        var encrypted_text = ""
        for (i in 0..rails) {
            for (j in 0..plain_text.size) {
                if (fence[i][j] != '\n') {
                    encrypted_text += fence[i][j]
                }
            }
        }
        return encrypted_text
    }
