import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {
    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(transform(expression))
        let result_stack = ArrayList<Decimal>()
        let temp = ArrayList<String>()
        for (s in postfix_stack.reversed()) {
            temp.add(s)
        }
        postfix_stack.clear()
        for (s in temp.reversed()) {
            postfix_stack.add(s)
        }
        while (!postfix_stack.isEmpty()) {
            let current_op = postfix_stack[postfix_stack.size() - 1]
            postfix_stack.popBack()
            if (!is_operator(current_op)) {
                let t = current_op.replace("~", "-")
                result_stack.add(Decimal(t))
            } else {
                let second = result_stack[result_stack.size() - 1]
                result_stack.popBack()
                let first = result_stack[result_stack.size() - 1]
                result_stack.popBack()
                let res = _calculate(first, second, current_op)
                result_stack.add(res)
            }
        }
        return result_stack[0].toFloat64()
    }

    public func prepare(expression: String): Unit {
        let op_stack = ArrayList<String>()
        op_stack.add(",")
        let arr = expression.toRuneArray()
        var current_index = 0
        var count = 0
        for (i in 0..arr.size) {
            let current_op = String([arr[i]])
            if (is_operator(current_op)) {
                if (count > 0) {
                    let sub = String(arr[current_index..(current_index + count)])
                    postfix_stack.add(sub)
                }
                let peek_op = op_stack[op_stack.size() - 1]
                if (current_op == ")") {
                    while (op_stack[op_stack.size() - 1] != "(") {
                        postfix_stack.add(op_stack[op_stack.size() - 1])
                        op_stack.popBack()
                    }
                    op_stack.popBack()
                } else {
                    while (current_op != "(" && peek_op != "," && compare(current_op, peek_op)) {
                        postfix_stack.add(op_stack[op_stack.size() - 1])
                        op_stack.popBack()
                        peek_op = op_stack[op_stack.size() - 1]
                    }
                    op_stack.add(current_op)
                }
                count = 0
                current_index = i + 1
            } else {
                count += 1
            }
        }
        if (count > 1 || (count == 1 && !is_operator(String([arr[current_index]])))) {
            let sub = String(arr[current_index..(current_index + count)])
            postfix_stack.add(sub)
        }
        while (op_stack[op_stack.size() - 1] != ",") {
            postfix_stack.add(op_stack[op_stack.size() - 1])
            op_stack.popBack()
        }
    }

    public static func is_operator(c: String): Bool {
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        var c = cur
        var p = peek
        if (c == "%") { c = "/" }
        if (p == "%") { p = "/" }
        let c_ord: Int64 = Int64(Rune(c[0]).code)
        let p_ord: Int64 = Int64(Rune(p[0]).code)
        return operat_priority[p_ord - 40] >= operat_priority[c_ord - 40]
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match (current_op) {
            case "+" => first_value + second_value
            case "-" => first_value - second_value
            case "*" => first_value * second_value
            case "/" => first_value / second_value
            case "%" => first_value % second_value
            case _ => Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        var expr = Regex("\\s+").replaceAll(expression, "")
        expr = Regex("=$").replaceAll(expr, "")
        let arr = expr.toRuneArray()
        for (i in 0..arr.size) {
            if (String([arr[i]]) == "-") {
                if (i == 0) {
                    arr[i] = '~'
                } else {
                    let prev = String([arr[i - 1]])
                    if (prev == "+" || prev == "-" || prev == "*" || prev == "/" || prev == "(" || prev == "E" || prev == "e") {
                        arr[i] = '~'
                    }
                }
            }
        }
        if (arr[0] == '~' && (arr.size > 1 && String([arr[1]]) == "(")) {
            arr[0] = '-'
            return "0" + String(arr)
        } else {
            return String(arr)
        }
    }
}

