import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if (!available_rooms.containsKey(room_type)) {
            return "false"
        }
        let avail = available_rooms[room_type]
        if (room_number <= avail) {
            if (!booked_rooms.containsKey(room_type)) {
                booked_rooms[room_type] = HashMap<String, Int64>()
            }
            booked_rooms[room_type][name] = room_number
            available_rooms[room_type] = avail - room_number
            return "Success!"
        } else if (avail != 0) {
            return Int64.toString(avail)
        } else {
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if (!booked_rooms.containsKey(room_type) || !booked_rooms[room_type].containsKey(name)) {
            return false
        }
        let booked = booked_rooms[room_type][name]
        if (room_number > booked) {
            return false
        } else if (room_number == booked) {
            booked_rooms[room_type].remove(name)
        } else {
            booked_rooms[room_type][name] = booked - room_number
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if (available_rooms.containsKey(room_type)) {
            available_rooms[room_type] = available_rooms[room_type] + room_number
        } else {
            available_rooms[room_type] = room_number
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        return available_rooms.getOrDefault(room_type, 0)
    }
}

