class IPAddress {
    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split('.')
        if (parts.size() != 4) {
            return false
        }
        for (part in parts) {
            match (Int64.parse(part)) {
                case Some(num) =>
                    if (num < 0 || num > 255) {
                        return false
                    }
                case None =>
                    return false
            }
        }
        true
    }

    public func get_octets(): ArrayList<String> {
        if (is_valid()) {
            return ArrayList(ip_address.split('.'))
        } else {
            return ArrayList<String>()
        }
    }

    public func get_binary(): String {
        if (!is_valid()) {
            return ""
        }
        let octets = ip_address.split('.')
        let binaryOctets = ArrayList<String>()
        for (octet in octets) {
            let num = Int64.parse(octet).getOrThrow()
            binaryOctets.append(num.format("08b"))
        }
        binaryOctets.join(".")
    }
}

