        var sumDiag: Float64 = 0.0
        var xsum = ArrayList<Float64>([])
        var ysum = ArrayList<Float64>([])
        var total: Float64 = 0.0

        for (i in 0..k) {
            xsum.append(0.0)
            for (j in 0..k) {
                xsum[i] += Float64(testData[i][j])
                total += Float64(testData[i][j])
            }
        }

        for (j in 0..k) {
            ysum.append(0.0)
            for (i in 0..k) {
                ysum[j] += Float64(testData[i][j])
            }
        }

        for (i in 0..k) {
            sumDiag += Float64(testData[i][i])
        }

        let P0 = sumDiag / total
        var Pe: Float64 = 0.0
        for (i in 0..k) {
            Pe += (xsum[i] * ysum[i])
        }
        Pe = Pe / (total * total)

        return (P0 - Pe) / (1.0 - Pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        var sumAll: Float64 = 0.0
        var P0: Float64 = 0.0

        for (i in 0..N) {
            var rowSum: Float64 = 0.0
            var temp: Float64 = 0.0
            for (j in 0..k) {
                let v = Float64(testData[i][j])
                rowSum += v
                temp += v * v
                sumAll += v
            }
            temp = (temp - Float64(n)) / (Float64(n - 1) * Float64(n))
            P0 += temp
        }
        P0 = P0 / Float64(N)

        var ysum = ArrayList<Float64>([])
        for (j in 0..k) {
            ysum.append(0.0)
            for (i in 0..N) {
                ysum[j] += Float64(testData[i][j])
            }
            ysum[j] = (ysum[j] / sumAll) * (ysum[j] / sumAll)
        }

        var Pe: Float64 = 0.0
        for (j in 0..k) {
            Pe += ysum[j]
        }

        return (P0 - Pe) / (1.0 - Pe)
    }
}

