import std.collection.ArrayList
import std.random.Random
import std.convert.Parsable
import std.collection.HashMap

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        var arr: ArrayList<ArrayList<Int64>> = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            var row = ArrayList<Int64>()
            for (j in 0..n) {
                row.append(0)
            }
            arr.append(row)
        }

        var rng = Random()
        var placed: Int64 = 0
        var minePos: HashMap<Int64, Int64> = HashMap<Int64, Int64>()

        while (placed < k) {
            let x = rng.nextInt64(n)
            let y = rng.nextInt64(n)
            let key = y * n + x
            if (!minePos.contains(key)) {
                minePos[key] = 1
                arr[y][x] = -1
                placed += 1
            }
        }

        let dx = [-1, -1, -1, 0, 0, 1, 1, 1]
        let dy = [-1, 0, 1, -1, 1, -1, 0, 1]

        for (y in 0..n) {
            for (x in 0..n) {
                if (arr[y][x] == -1) {
                    continue
                }
                var count: Int64 = 0
                for (d in 0..8) {
                    let nx = x + dx[d]
                    let ny = y + dy[d]
                    if (nx >= 0 && nx < n && ny >= 0 && ny < n && arr[ny][nx] == -1) {
                        count += 1
                    }
                }
                arr[y][x] = count
            }
        }

        var result: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        for (y in 0..n) {
            var row = ArrayList<String>()
            for (x in 0..n) {
                if (arr[y][x] == -1) {
                    row.append("X")
                } else {
                    row.append(arr[y][x].toString())
                }
            }
            result.append(row)
        }
        return result
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        var arr: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            var row = ArrayList<String>()
            for (j in 0..n) {
                row.append("-")
            }
            arr.append(row)
        }
        return arr
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-" && minesweeper_map[i][j] != "X") {
                    return false
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (minesweeper_map[x][y] == "X") {
            return false
        } else {
            player_map[x][y] = minesweeper_map[x][y]
            score += 1
            if (check_won(player_map)) {
                return true
            }
            return player_map
        }
    }
}

