class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(s) => this.format_string(s)
            case None => ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split(".")
        let lstr = parts[0]
        let rstr = parts.size() > 1 ? parts[1] : ""
        let lstrrev = lstr.reverse()
        var a = Array<String>(5, item: "")
        let len = lstrrev.size()

        if (len % 3 == 1) {
            lstrrev += "00"
        } else if (len % 3 == 2) {
            lstrrev += "0"
        }

        var lm = ""
        for (i in 0..(lstrrev.size() / 3)) {
            a[i] = lstrrev[3*i..3*i+3].reverse()
            if (a[i] != "000") {
                lm = this.trans_three(a[i]) + " " + this.parse_more(Int64(i)) + " " + lm
            }
        }

        let xs = rstr.isEmpty() ? "" : "AND CENTS ${this.trans_two(rstr)} "
        if (lm.trim().isEmpty()) {
            return "ZERO ONLY"
        } else {
            return "${lm.trim()} ${xs}ONLY"
        }
    }

    public func trans_two(s: String): String {
        let t = s.padStart(2, '0')
        if (t[0] == '0') {
            return this.NUMBER[t[1].toInt64()]
        } else if (t[0] == '1') {
            return this.NUMBER_TEEN[t.toInt64() - 10]
        } else if (t[1] == '0') {
            return this.NUMBER_TEN[t[0].toInt64() - 1]
        } else {
            return "${this.NUMBER_TEN[t[0].toInt64() - 1]} ${this.NUMBER[t[1].toInt64()]}"
        }
    }

    public func trans_three(s: String): String {
        if (s[0] == '0') {
            return this.trans_two(s[1..])
        } else if (s[1..] == "00") {
            return "${this.NUMBER[s[0].toInt64()]} HUNDRED"
        } else {
            return "${this.NUMBER[s[0].toInt64()]} HUNDRED AND ${this.trans_two(s[1..])}"
        }
    }

    public func parse_more(i: Int64): String {
        this.NUMBER_MORE[i]
    }
}

