class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let out = ArrayList<Rune>()
        let chars = string.toRuneArray()
        let length = chars.size()
        var pos = 0

        while (pos < length - 2) {
            if (chars[pos] == r'&' && chars[pos + 1] == r'#') {
                var start = pos + 2
                var isHex = false
                let firstChar = chars[start]

                if (firstChar == r'x' || firstChar == r'X') {
                    start += 1
                    isHex = true
                }

                if (start == length) {
                    break
                }

                var end = start
                while (end < length && is_hex_char(chars[end])) {
                    end += 1
                }

                if (end < length && chars[end] == r';') {
                    let sub = string.substring(start, end)
                    let value = if (isHex) {
                        Int64.parse(sub, 16)
                    } else {
                        Int64.parse(sub, 10)
                    }
                    out.append(Rune.fromInt(value))
                    pos = end + 1
                    continue
                }
            }
            out.append(chars[pos])
            pos += 1
        }

        while (pos < length) {
            out.append(chars[pos])
            pos += 1
        }

        return String.fromRuneArray(out)
    }

    public static func is_hex_char(char: Rune): Bool {
        return char.isDigit() || (r'a' <= char.lowercase() && char.lowercase() <= r'f')
    }
}

