        if (page_number < 1 || page_number > total_pages) {
            return ArrayList<Int64>()
        }
        let start = ((page_number - 1) * page_size).toInt64()
        let end = (start + page_size).toInt64()
        let res = ArrayList<Int64>()
        for (i in start..end) {
            if (i >= total_items) {
                break
            }
            res.append(data[i])
        }
        res
    }

    public func get_page_info(page_number: Int64): Option<PageInfo> {
        if (page_number < 1 || page_number > total_pages) {
            return None
        }
        let start = ((page_number - 1) * page_size).toInt64()
        let end = min(start + page_size, total_items)
        let pageData = ArrayList<Int64>()
        for (i in start..end) {
            pageData.append(data[i])
        }
        Some(PageInfo(
            current_page: page_number,
            per_page: page_size,
            total_pages: total_pages,
            total_items: total_items,
            has_previous: page_number > 1,
            has_next: page_number < total_pages,
            data: pageData
        ))
    }

    public func search(keyword: String): SearchInfo {
        let results = ArrayList<Int64>()
        for (item in data) {
            if (item.toString().contains(keyword)) {
                results.append(item)
            }
        }
        let totalResults = results.size.toInt64()
        let totalPages = (totalResults + page_size - 1) / page_size
        SearchInfo(
            keyword: keyword,
            total_results: totalResults,
            total_pages: totalPages,
            results: results
        )
    }
