class Statistics3 {
    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        let sorted = data.clone()
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 1) {
            return Float64(sorted[n / 2])
        } else {
            return (Float64(sorted[n / 2 - 1]) + Float64(sorted[n / 2])) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let counts = HashMap<Int64, Int64>()
        for (v in data) {
            counts[v] = counts.getOrDefault(v, 0) + 1
        }
        var maxCount = 0
        for ((_, c) in counts) {
            if (c > maxCount) {
                maxCount = c
            }
        }
        let modes = ArrayList<Int64>()
        for ((v, c) in counts) {
            if (c == maxCount) {
                modes.append(v)
            }
        }
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        let n = x.size
        if (n != y.size || n == 0) {
            return None
        }
        var sumX = 0
        var sumY = 0
        for (i in 0..n) {
            sumX += x[i]
            sumY += y[i]
        }
        let meanX = Float64(sumX) / Float64(n)
        let meanY = Float64(sumY) / Float64(n)
        var num = 0.0
        var denX = 0.0
        var denY = 0.0
        for (i in 0..n) {
            let dx = Float64(x[i]) - meanX
            let dy = Float64(y[i]) - meanY
            num += dx * dy
            denX += dx * dx
            denY += dy * dy
        }
        if (denX == 0.0 || denY == 0.0) {
            return None
        }
        return Some(num / (sqrt(denX) * sqrt(denY)))
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None
        }
        var sum = 0
        for (v in data) {
            sum += v
        }
        return Some(Float64(sum) / Float64(data.size))
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let rows = data.size
        if (rows == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let cols = data[0].size
        let mat = ArrayList<ArrayList<Float64>>()
        for (i in 0..cols) {
            let row = ArrayList<Float64>()
            for (j in 0..cols) {
                let col1 = ArrayList<Int64>()
                let col2 = ArrayList<Int64>()
                for (r in 0..rows) {
                    col1.append(data[r][i])
                    col2.append(data[r][j])
                }
                let corr = correlation(col1, col2)
                row.append(corr match {
                    case Some(v) => v
                    case None => 0.0
                })
            }
            mat.append(row)
        }
        return mat
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let n = data.size
        if (n < 2) {
            return None
        }
        let m = mean(data)
        match (m) {
            case None => return None
            case Some(meanVal) =>
                var sum = 0.0
                for (v in data) {
                    let diff = Float64(v) - meanVal
                    sum += diff * diff
                }
                let variance = sum / Float64(n - 1)
                return Some(sqrt(variance))
        }
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let sd = standard_deviation(data)
        match (m, sd) {
            case (Some(meanVal), Some(stdVal)) =>
                if (stdVal == 0.0) {
                    return None
                }
                let zs = ArrayList<Float64>()
                for (v in data) {
                    zs.append((Float64(v) - meanVal) / stdVal)
                }
                return Some(zs)
            case _ => return None
        }
    }
