import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        round(taylor(x, 50), 10)
    }

    public func factorial(a: Int64): Decimal {
        var b = Decimal(1)
        var c = a
        while (c != 1) {
            b *= Decimal(c)
            c -= 1
        }
        b
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var a = 1.0
        let xRad = x / 180.0 * PI
        var count = 1
        for (k in 1..n) {
            let term = pow(xRad, 2.0 * Float64(k)) / Float64(Int64(factorial(2 * Int64(k))))
            if (count % 2 != 0) {
                a -= term
            } else {
                a += term
            }
            count += 1
        }
        a
    }

    public func sin(x: Float64): Float64 {
        let xRad = x / 180.0 * PI
        var g = 0.0
        var t = xRad
        var n = 1
        while (abs(t) >= 1e-15) {
            g += t
            n += 1
            t = -t * xRad * xRad / (2.0 * Float64(n) - 1.0) / (2.0 * Float64(n) - 2.0)
        }
        round(g, 10)
    }

    public func tan(x: Float64): Option<Float64> {
        let c = cos(x)
        if (abs(c - 0.0) > 0.000001) {
            Some(round(sin(x) / c, 10))
        } else {
            None
        }
    }
}

