    }
    public func parse(input: Input): ParseResult < T > {
        return parseWithRecovery(input, 0)
    }
    private func parseWithRecovery(input: Input, errorCount: Int64): ParseResult < T > {
        if(errorCount >= this.maxErrors) {
            return Failure(ParseError("Too many errors, stopping parse", input.getPosition()))
        }
        match(this.baseParser.parse(input)) {
            case Success(value, remaining) => Success(value, remaining)
            case Failure(error) => handleFailure(input, error, errorCount)
            case Incomplete(n) => Incomplete(n)
        }
    }
    private func handleFailure(input: Input, error: ParseError, errorCount: Int64): ParseResult < T > {
        let detailedError = createDetailedError(input, error)
        this.errorCollector.addError(detailedError)
        let recoveredInput = skipToNextToken(input)
        if(recoveredInput.getPosition().offset > input.getPosition().offset) {
            return parseWithRecovery(recoveredInput, errorCount + 1)
        }
        else {
