class URLHandler {
    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let schemeEnd = url.find("://")
        if (schemeEnd != -1) {
            return Some(url[..schemeEnd])
        }
        return None
    }

    public func get_host(): Option<String> {
        let schemeEnd = url.find("://")
        if (schemeEnd != -1) {
            let urlWithoutScheme = url[schemeEnd + 3..]
            let hostEnd = urlWithoutScheme.find("/")
            if (hostEnd != -1) {
                return Some(urlWithoutScheme[..hostEnd])
            }
            return Some(urlWithoutScheme)
        }
        return None
    }

