            if (fixed.size > 0) {
                let parts = fixed.split("/")
                for (part in parts) {
                    this.segments.append(Uri.decode(part))
                }
            }
        }
    }

    public static func fix_path(path: String): String {
        if (path.isEmpty()) {
            return ""
        }
        var s = path.trimStart("/")
        s = s.trimEnd("/")
        return s
    }
