import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {
    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let norm1 = sqrt(vector_1.fold(0.0, {acc, x => acc + x * x}))
        let norm2 = sqrt(vector_2.fold(0.0, {acc, x => acc + x * x}))
        var dot = 0.0
        for (i in 0..vector_1.size) {
            dot += vector_1[i] * vector_2[i]
        }
        return dot / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let norm1 = sqrt(vector_1.fold(0.0, {acc, x => acc + x * x}))
        var result = ArrayList<Float64>()
        for (vec in vectors_all) {
            var dot = 0.0
            var norm2 = 0.0
            for (i in 0..vec.size) {
                dot += vector_1[i] * vec[i]
                norm2 += vec[i] * vec[i]
            }
            result.add(dot / (norm1 * sqrt(norm2)))
        }
        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        if (vector_list_1.isEmpty() || vector_list_2.isEmpty()) {
            throw ZeroDivisionError("At least one of the passed list is empty.")
        }
        let mean1 = meanVector(vector_list_1)
        let mean2 = meanVector(vector_list_2)
        return similarity(mean1, mean2)
    }

    private static func meanVector(vecs: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let dim = vecs[0].size
        let mean = ArrayList<Float64>(dim, {_ => 0.0})
        for (vec in vecs) {
            for (i in 0..dim) {
                mean[i] += vec[i]
            }
        }
        for (i in 0..dim) {
            mean[i] /= vecs.size.toFloat64
        }
        return mean
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for ((key, count) in number_dict) {
            let weight = log((total_num + 1.0) / (count + 1.0))
            result[key] = weight
        }
        return result
    }
}

